    CapacityUnitsConfiguration.add_member(:storage_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageCapacityUnit, location_name: 'StorageCapacityUnits', traits: {"smithy.api#documentation" => "<p>The amount of extra storage capacity for an index. A single capacity unit provides 30 GB\n      of storage space or 100,000 documents, whichever is reached first. You can add up to 100 extra\n      capacity units.</p>", "smithy.api#required" => {}}))
    CapacityUnitsConfiguration.add_member(:query_capacity_units, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryCapacityUnit, location_name: 'QueryCapacityUnits', traits: {"smithy.api#documentation" => "<p>The amount of extra query capacity for an index and <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/API_GetQuerySuggestions.html\">GetQuerySuggestions</a>\n      capacity.</p>\n         <p>A single extra capacity unit for an index provides 0.1 queries per second or approximately\n      8,000 queries per day. You can add up to 100 extra capacity units.</p>\n         <p>\n            <code>GetQuerySuggestions</code> capacity is five times the provisioned query capacity for\n      an index, or the base capacity of 2.5 calls per second, whichever is higher. For example, the\n      base capacity for an index is 0.1 queries per second, and <code>GetQuerySuggestions</code>\n      capacity has a base of 2.5 calls per second. If you add another 0.1 queries per second to\n      total 0.2 queries per second for an index, the <code>GetQuerySuggestions</code> capacity is\n      2.5 calls per second (higher than five times 0.2 queries per second).</p>", "smithy.api#required" => {}}))
