    ConfluenceConfiguration.add_member(:server_url, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'ServerUrl', traits: {"smithy.api#documentation" => "<p>The URL of your Confluence instance. Use the full URL of the server. For example,\n                <i>https://server.example.com:port/</i>. You can also use an IP\n            address, for example, <i>https://192.168.1.113/</i>.</p>", "smithy.api#required" => {}}))
    ConfluenceConfiguration.add_member(:secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretArn, location_name: 'SecretArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Secrets Manager secret that contains the\n            user name and password required to connect to the Confluence instance. If you use\n            Confluence Cloud, you use a generated API token as the password.</p>\n         <p>You can also provide authentication credentials in the form of a personal access\n            token. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/data-source-confluence.html\">Using a Confluence data\n                source</a>.</p>", "smithy.api#required" => {}}))
