    FsxConfiguration.add_member(:file_system_type, Smithy::Schema::Shapes::ShapeRef.new(shape: FsxFileSystemType, location_name: 'FileSystemType', traits: {"smithy.api#documentation" => "<p>The Amazon FSx file system type. Windows is currently the only supported\n            type.</p>", "smithy.api#required" => {}}))
    FsxConfiguration.add_member(:vpc_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceVpcConfiguration, location_name: 'VpcConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information for an Amazon Virtual Private Cloud to connect to your Amazon FSx. Your Amazon FSx instance must reside inside your VPC.</p>", "smithy.api#required" => {}}))
    FsxConfiguration.add_member(:secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretArn, location_name: 'SecretArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Secrets Manager secret that contains the\n            key-value pairs required to connect to your Amazon FSx file system. Windows is\n            currently the only supported type. The secret must contain a JSON structure with the\n            following keys:</p>\n         <ul>\n            <li>\n               <p>username—The Active Directory user name, along with the Domain Name\n                    System (DNS) domain name. For example,\n                        <i>user@corp.example.com</i>. The Active Directory user\n                    account must have read and mounting access to the Amazon FSx file system\n                    for Windows.</p>\n            </li>\n            <li>\n               <p>password—The password of the Active Directory user account with read\n                    and mounting access to the Amazon FSx Windows file system.</p>\n            </li>\n         </ul>"}))
    FsxConfiguration.add_member(:inclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'InclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to include certain files in your Amazon FSx file system. Files that match the patterns are included in the index.\n            Files that don't match the patterns are excluded from the index. If a file matches both\n            an inclusion and exclusion pattern, the exclusion pattern takes precedence and the file\n            isn't included in the index.</p>"}))
    FsxConfiguration.add_member(:exclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'ExclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to exclude certain files in your Amazon FSx file system. Files that match the patterns are excluded from the index.\n            Files that don't match the patterns are included in the index. If a file matches both an\n            inclusion and exclusion pattern, the exclusion pattern takes precedence and the file\n            isn't included in the index.</p>"}))
    FsxConfiguration.add_member(:field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'FieldMappings', traits: {"smithy.api#documentation" => "<p>A list of <code>DataSourceToIndexFieldMapping</code> objects that map Amazon FSx data source attributes or field names to Amazon Kendra index field names. To\n            create custom fields, use the <code>UpdateIndex</code> API before you map to Amazon FSx fields. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The\n                Amazon FSx data source field names must exist in your Amazon FSx\n            custom metadata.</p>"}))
