    GetQuerySuggestionsRequest.add_member(:index_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexId, location_name: 'IndexId', traits: {"smithy.api#documentation" => "<p>The identifier of the index you want to get query suggestions from.</p>", "smithy.api#required" => {}}))
    GetQuerySuggestionsRequest.add_member(:query_text, Smithy::Schema::Shapes::ShapeRef.new(shape: SuggestionQueryText, location_name: 'QueryText', traits: {"smithy.api#documentation" => "<p>The text of a user's query to generate query suggestions.</p>\n         <p>A query is suggested if the query prefix matches \n            what a user starts to type as their query.</p>\n         <p>Amazon Kendra does not show any suggestions if a user \n            types fewer than two characters or more than 60 characters. \n            A query must also have at least one search result and contain \n            at least one word of more than four characters.</p>", "smithy.api#required" => {}}))
    GetQuerySuggestionsRequest.add_member(:max_suggestions_count, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxSuggestionsCount', traits: {"smithy.api#documentation" => "<p>The maximum number of query suggestions you want to show \n            to your users.</p>"}))
    GetQuerySuggestionsRequest.add_member(:suggestion_types, Smithy::Schema::Shapes::ShapeRef.new(shape: SuggestionTypes, location_name: 'SuggestionTypes', traits: {"smithy.api#documentation" => "<p>The suggestions type to base query suggestions on. The suggestion \n            types are query history or document fields/attributes. You can set \n            one type or the other.</p>\n         <p>If you set query history as your suggestions type, Amazon Kendra \n            suggests queries relevant to your users based on popular queries in \n            the query history.</p>\n         <p>If you set document fields/attributes as your suggestions type, \n            Amazon Kendra suggests queries relevant to your users based on the \n            contents of document fields.</p>"}))
    GetQuerySuggestionsRequest.add_member(:attribute_suggestions_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeSuggestionsGetConfig, location_name: 'AttributeSuggestionsConfig', traits: {"smithy.api#documentation" => "<p>Configuration information for the document fields/attributes that you \n            want to base query suggestions on.</p>"}))
