    GetSnapshotsRequest.add_member(:index_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexId, location_name: 'IndexId', traits: {"smithy.api#documentation" => "<p>The identifier of the index to get search metrics data.</p>", "smithy.api#required" => {}}))
    GetSnapshotsRequest.add_member(:interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Interval, location_name: 'Interval', traits: {"smithy.api#documentation" => "<p>The time interval or time window to get search metrics data. The time interval uses\n            the time zone of your index. You can view data in the following time windows:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>THIS_WEEK</code>: The current week, starting on the Sunday and ending on\n                    the day before the current date.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ONE_WEEK_AGO</code>: The previous week, starting on the Sunday and\n                    ending on the following Saturday.</p>\n            </li>\n            <li>\n               <p>\n                  <code>TWO_WEEKS_AGO</code>: The week before the previous week, starting on the\n                    Sunday and ending on the following Saturday.</p>\n            </li>\n            <li>\n               <p>\n                  <code>THIS_MONTH</code>: The current month, starting on the first day of the\n                    month and ending on the day before the current date.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ONE_MONTH_AGO</code>: The previous month, starting on the first day of\n                    the month and ending on the last day of the month.</p>\n            </li>\n            <li>\n               <p>\n                  <code>TWO_MONTHS_AGO</code>: The month before the previous month, starting on\n                    the first day of the month and ending on last day of the month.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    GetSnapshotsRequest.add_member(:metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricType, location_name: 'MetricType', traits: {"smithy.api#documentation" => "<p>The metric you want to retrieve. You can specify only one metric per call.</p>\n         <p>For more information about the metrics you can view, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/search-analytics.html\">Gaining insights with search\n                analytics</a>.</p>", "smithy.api#required" => {}}))
    GetSnapshotsRequest.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>If the previous response was incomplete (because there is more data to retrieve),\n                Amazon Kendra returns a pagination token in the response. You can use this\n            pagination token to retrieve the next set of search metrics data.</p>"}))
    GetSnapshotsRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of returned data for the metric.</p>"}))
    GetSnapshotsRequest.type = Types::GetSnapshotsRequest
    GetSnapshotsResponse.add_member(:snap_shot_time_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeRange, location_name: 'SnapShotTimeFilter', traits: {"smithy.api#documentation" => "<p>The Unix timestamp for the beginning and end of the time window for the \n            search metrics data.</p>"}))
    GetSnapshotsResponse.add_member(:snapshots_data_header, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotsDataHeaderFields, location_name: 'SnapshotsDataHeader', traits: {"smithy.api#documentation" => "<p>The column headers for the search metrics data.</p>"}))
    GetSnapshotsResponse.add_member(:snapshots_data, Smithy::Schema::Shapes::ShapeRef.new(shape: SnapshotsDataRecords, location_name: 'SnapshotsData', traits: {"smithy.api#documentation" => "<p>The search metrics data. The data returned depends on the metric type you\n            requested.</p>"}))
    GetSnapshotsResponse.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>If the response is truncated, Amazon Kendra returns this token, which you can use\n            in a later request to retrieve the next set of search metrics data.</p>"}))
