    GitHubConfiguration.add_member(:exclusion_file_name_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExclusionFileNamePatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to exclude certain file names in your GitHub\n            repository or repositories. File names that match the patterns are excluded from the\n            index. File names that don't match the patterns are included in the index. If a file\n            matches both an exclusion and inclusion pattern, the exclusion pattern takes precedence\n            and the file isn't included in the index.</p>"}))
    GitHubConfiguration.add_member(:vpc_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceVpcConfiguration, location_name: 'VpcConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information of an Amazon Virtual Private Cloud to connect to your GitHub. For\n            more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/vpc-configuration.html\">Configuring a VPC</a>.</p>"}))
    GitHubConfiguration.add_member(:git_hub_repository_configuration_field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'GitHubRepositoryConfigurationFieldMappings', traits: {"smithy.api#documentation" => "<p>A list of <code>DataSourceToIndexFieldMapping</code> objects that map GitHub\n            repository attributes or field names to Amazon Kendra index field names. To create\n            custom fields, use the <code>UpdateIndex</code> API before you map to GitHub fields. For\n            more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The\n            GitHub data source field names must exist in your GitHub custom metadata.</p>"}))
