    QueryRequest.add_member(:query_text, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryText, location_name: 'QueryText', traits: {"smithy.api#documentation" => "<p>The input query text for the search. Amazon Kendra truncates queries at 30 token\n         words, which excludes punctuation and stop words. Truncation still applies if you use\n         Boolean or more advanced, complex queries. For example, <code>Timeoff AND October AND\n            Category:HR</code> is counted as 3 tokens: <code>timeoff</code>, <code>october</code>,\n            <code>hr</code>. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/searching-example.html#searching-index-query-syntax\">Searching with advanced query syntax</a> in the Amazon Kendra Developer Guide. </p>"}))
    QueryRequest.add_member(:attribute_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeFilter, location_name: 'AttributeFilter', traits: {"smithy.api#documentation" => "<p>Filters search results by document fields/attributes. You can only provide one attribute\n         filter; however, the <code>AndAllFilters</code>, <code>NotFilter</code>, and\n            <code>OrAllFilters</code> parameters contain a list of other filters.</p>\n         <p>The <code>AttributeFilter</code> parameter means you can create a set of filtering rules\n         that a document must satisfy to be included in the query results.</p>\n         <note>\n            <p>For Amazon Kendra Gen AI Enterprise Edition indices use <code>AttributeFilter</code> to\n            enable document filtering for end users using <code>_email_id</code> or include public\n            documents (<code>_email_id=null</code>).</p>\n         </note>"}))
    QueryRequest.add_member(:facets, Smithy::Schema::Shapes::ShapeRef.new(shape: FacetList, location_name: 'Facets', traits: {"smithy.api#documentation" => "<p>An array of documents fields/attributes for faceted search. Amazon Kendra returns a\n         count for each field key specified. This helps your users narrow their search.</p>"}))
    QueryRequest.add_member(:requested_document_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentAttributeKeyList, location_name: 'RequestedDocumentAttributes', traits: {"smithy.api#documentation" => "<p>An array of document fields/attributes to include in the response. You can limit the\n         response to include certain document fields. By default, all document attributes are\n         included in the response.</p>"}))
    QueryRequest.add_member(:query_result_type_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryResultType, location_name: 'QueryResultTypeFilter', traits: {"smithy.api#documentation" => "<p>Sets the type of query result or response. Only results for the specified type are\n         returned.</p>"}))
    QueryRequest.add_member(:document_relevance_override_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentRelevanceOverrideConfigurationList, location_name: 'DocumentRelevanceOverrideConfigurations', traits: {"smithy.api#documentation" => "<p>Overrides relevance tuning configurations of fields/attributes set at the index\n         level.</p>\n         <p>If you use this API to override the relevance tuning configured at the index level, but\n         there is no relevance tuning configured at the index level, then Amazon Kendra does\n         not apply any relevance tuning.</p>\n         <p>If there is relevance tuning configured for fields at the index level, and you use this\n         API to override only some of these fields, then for the fields you did not override, the\n         importance is set to 1.</p>"}))
    QueryRequest.add_member(:page_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PageNumber', traits: {"smithy.api#documentation" => "<p>Query results are returned in pages the size of the <code>PageSize</code> parameter. By\n         default, Amazon Kendra returns the first page of results. Use this parameter to get\n         result pages after the first one.</p>"}))
    QueryRequest.add_member(:page_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PageSize', traits: {"smithy.api#documentation" => "<p>Sets the number of results that are returned in each page of results. The default page\n         size is 10. The maximum number of results returned is 100. If you ask for more than 100\n         results, only 100 are returned.</p>"}))
    QueryRequest.add_member(:sorting_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SortingConfiguration, location_name: 'SortingConfiguration', traits: {"smithy.api#documentation" => "<p>Provides information that determines how the results of the query are sorted. You can\n         set the field that Amazon Kendra should sort the results on, and specify whether the\n         results should be sorted in ascending or descending order. In the case of ties in sorting\n         the results, the results are sorted by relevance.</p>\n         <p>If you don't provide sorting configuration, the results are sorted by the relevance that\n            Amazon Kendra determines for the result.</p>"}))
    QueryRequest.add_member(:sorting_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: SortingConfigurationList, location_name: 'SortingConfigurations', traits: {"smithy.api#documentation" => "<p>Provides configuration information to determine how the results of a query are\n         sorted.</p>\n         <p>You can set upto 3 fields that Amazon Kendra should sort the results on, and\n         specify whether the results should be sorted in ascending or descending order. The sort\n         field quota can be increased.</p>\n         <p>If you don't provide a sorting configuration, the results are sorted by the relevance\n         that Amazon Kendra determines for the result. In the case of ties in sorting the\n         results, the results are sorted by relevance. </p>"}))
    QueryRequest.add_member(:user_context, Smithy::Schema::Shapes::ShapeRef.new(shape: UserContext, location_name: 'UserContext', traits: {"smithy.api#documentation" => "<p>The user context token or user and group information.</p>"}))
    QueryRequest.add_member(:visitor_id, Smithy::Schema::Shapes::ShapeRef.new(shape: VisitorId, location_name: 'VisitorId', traits: {"smithy.api#documentation" => "<p>Provides an identifier for a specific user. The <code>VisitorId</code> should be a\n         unique identifier, such as a GUID. Don't use personally identifiable information, such as\n         the user's email address, as the <code>VisitorId</code>.</p>"}))
    QueryRequest.add_member(:spell_correction_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SpellCorrectionConfiguration, location_name: 'SpellCorrectionConfiguration', traits: {"smithy.api#documentation" => "<p>Enables suggested spell corrections for queries.</p>"}))
    QueryRequest.add_member(:collapse_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CollapseConfiguration, location_name: 'CollapseConfiguration', traits: {"smithy.api#documentation" => "<p>Provides configuration to determine how to group results by document attribute value,\n         and how to display them (collapsed or expanded) under a designated primary document for\n         each group.</p>"}))
    QueryRequest.type = Types::QueryRequest
    QueryResult.add_member(:query_id, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryId, location_name: 'QueryId', traits: {"smithy.api#documentation" => "<p>The identifier for the search. You also use <code>QueryId</code> to identify the search\n         when using the <a href=\"https://docs.aws.amazon.com/kendra/latest/APIReference/API_SubmitFeedback.html\">SubmitFeedback</a>\n         API.</p>"}))
    QueryResult.add_member(:result_items, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryResultItemList, location_name: 'ResultItems', traits: {"smithy.api#documentation" => "<p>The results of the search.</p>"}))
    QueryResult.add_member(:facet_results, Smithy::Schema::Shapes::ShapeRef.new(shape: FacetResultList, location_name: 'FacetResults', traits: {"smithy.api#documentation" => "<p>Contains the facet results. A <code>FacetResult</code> contains the counts for each\n         field/attribute key that was specified in the <code>Facets</code> input parameter.</p>"}))
    QueryResult.add_member(:total_number_of_results, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'TotalNumberOfResults', traits: {"smithy.api#documentation" => "<p>The total number of items found by the search. However, you can only retrieve up to 100\n         items. For example, if the search found 192 items, you can only retrieve the first 100 of\n         the items.</p>"}))
    QueryResult.add_member(:warnings, Smithy::Schema::Shapes::ShapeRef.new(shape: WarningList, location_name: 'Warnings', traits: {"smithy.api#documentation" => "<p>A list of warning codes and their messages on problems with your query.</p>\n         <p>Amazon Kendra currently only supports one type of warning, which is a warning on\n         invalid syntax used in the query. For examples of invalid query syntax, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/searching-example.html#searching-index-query-syntax\">Searching\n            with advanced query syntax</a>.</p>"}))
    QueryResult.add_member(:spell_corrected_queries, Smithy::Schema::Shapes::ShapeRef.new(shape: SpellCorrectedQueryList, location_name: 'SpellCorrectedQueries', traits: {"smithy.api#documentation" => "<p>A list of information related to suggested spell corrections for a query.</p>"}))
    QueryResult.add_member(:featured_results_items, Smithy::Schema::Shapes::ShapeRef.new(shape: FeaturedResultsItemList, location_name: 'FeaturedResultsItems', traits: {"smithy.api#documentation" => "<p>The list of featured result items. Featured results are displayed at the top of the\n         search results page, placed above all other results for certain queries. If there's an\n         exact match of a query, then certain documents are featured in the search results.</p>"}))
    QueryResult.type = Types::QueryResult
