    QueryResultItem.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: ResultId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>The unique identifier for the query result item id (<code>Id</code>) and the query\n         result item document id (<code>DocumentId</code>) combined. The value of this field changes\n         with every request, even when you have the same documents.</p>"}))
    QueryResultItem.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryResultType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>The type of document within the response. For example, a response could include a\n         question-answer that's relevant to the query.</p>"}))
    QueryResultItem.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryResultFormat, location_name: 'Format', traits: {"smithy.api#documentation" => "<p>If the <code>Type</code> of document within the response is <code>ANSWER</code>, then it\n         is either a <code>TABLE</code> answer or <code>TEXT</code> answer. If it's a table answer,\n         a table excerpt is returned in <code>TableExcerpt</code>. If it's a text answer, a text\n         excerpt is returned in <code>DocumentExcerpt</code>.</p>"}))
    QueryResultItem.add_member(:additional_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: AdditionalResultAttributeList, location_name: 'AdditionalAttributes', traits: {"smithy.api#documentation" => "<p>One or more additional fields/attributes associated with the query result.</p>"}))
    QueryResultItem.add_member(:document_id, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentId, location_name: 'DocumentId', traits: {"smithy.api#documentation" => "<p>The identifier for the document.</p>"}))
    QueryResultItem.add_member(:document_title, Smithy::Schema::Shapes::ShapeRef.new(shape: TextWithHighlights, location_name: 'DocumentTitle', traits: {"smithy.api#documentation" => "<p>The title of the document. Contains the text of the title and information for\n         highlighting the relevant terms in the title.</p>"}))
    QueryResultItem.add_member(:document_excerpt, Smithy::Schema::Shapes::ShapeRef.new(shape: TextWithHighlights, location_name: 'DocumentExcerpt', traits: {"smithy.api#documentation" => "<p>An extract of the text in the document. Contains information about highlighting the\n         relevant terms in the excerpt.</p>"}))
    QueryResultItem.add_member(:document_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'DocumentURI', traits: {"smithy.api#documentation" => "<p>The URI of the original location of the document.</p>"}))
    QueryResultItem.add_member(:document_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentAttributeList, location_name: 'DocumentAttributes', traits: {"smithy.api#documentation" => "<p>An array of document fields/attributes assigned to a document in the search results. For\n         example, the document author (<code>_author</code>) or the source URI\n            (<code>_source_uri</code>) of the document.</p>"}))
    QueryResultItem.add_member(:score_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: ScoreAttributes, location_name: 'ScoreAttributes', traits: {"smithy.api#documentation" => "<p>Indicates the confidence level of Amazon Kendra providing a relevant result for the\n         query. Each result is placed into a bin that indicates the confidence,\n            <code>VERY_HIGH</code>, <code>HIGH</code>, <code>MEDIUM</code> and <code>LOW</code>. You\n         can use the score to determine if a response meets the confidence needed for your\n         application.</p>\n         <p>The field is only set to <code>LOW</code> when the <code>Type</code> field is set to\n            <code>DOCUMENT</code> and Amazon Kendra is not confident that the result is\n         relevant to the query.</p>"}))
    QueryResultItem.add_member(:feedback_token, Smithy::Schema::Shapes::ShapeRef.new(shape: FeedbackToken, location_name: 'FeedbackToken', traits: {"smithy.api#documentation" => "<p>A token that identifies a particular result from a particular query. Use this token to\n         provide click-through feedback for the result. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/submitting-feedback.html\">Submitting\n            feedback</a>.</p>"}))
    QueryResultItem.add_member(:table_excerpt, Smithy::Schema::Shapes::ShapeRef.new(shape: TableExcerpt, location_name: 'TableExcerpt', traits: {"smithy.api#documentation" => "<p>An excerpt from a table within a document.</p>"}))
