    QuipConfiguration.add_member(:secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretArn, location_name: 'SecretArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Secrets Manager secret that contains the\n            key-value pairs that are required to connect to your Quip. The secret must contain a\n            JSON structure with the following keys:</p>\n         <ul>\n            <li>\n               <p>accessToken—The token created in Quip. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/data-source-slack.html\">Using a\n                        Quip data source</a>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    QuipConfiguration.add_member(:crawl_file_comments, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CrawlFileComments', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>\n            <code>TRUE</code> to index file comments.</p>"}))
    QuipConfiguration.add_member(:crawl_chat_rooms, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CrawlChatRooms', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>\n            <code>TRUE</code> to index the contents of chat rooms.</p>"}))
    QuipConfiguration.add_member(:crawl_attachments, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CrawlAttachments', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>\n            <code>TRUE</code> to index attachments.</p>"}))
    QuipConfiguration.add_member(:folder_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: FolderIdList, location_name: 'FolderIds', traits: {"smithy.api#documentation" => "<p>The identifiers of the Quip folders you want to index. You can find the folder ID in\n            your browser URL when you access your folder in Quip. For example,\n                <i>https://quip-company.quipdomain.com/zlLuOVNSarTL/folder-name</i>.\n            The folder ID in this example is \"zlLuOVNSarTL\".</p>"}))
    QuipConfiguration.add_member(:thread_field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'ThreadFieldMappings', traits: {"smithy.api#documentation" => "<p>A list of <code>DataSourceToIndexFieldMapping</code> objects that map attributes or\n            field names of Quip threads to Amazon Kendra index field names. To create custom\n            fields, use the <code>UpdateIndex</code> API before you map to Quip fields. For more\n            information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The Quip field names must exist in your Quip\n            custom metadata.</p>"}))
    QuipConfiguration.add_member(:message_field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'MessageFieldMappings', traits: {"smithy.api#documentation" => "<p>A list of <code>DataSourceToIndexFieldMapping</code> objects that map attributes or\n            field names of Quip messages to Amazon Kendra index field names. To create custom\n            fields, use the <code>UpdateIndex</code> API before you map to Quip fields. For more\n            information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The Quip field names must exist in your Quip\n            custom metadata.</p>"}))
    QuipConfiguration.add_member(:attachment_field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'AttachmentFieldMappings', traits: {"smithy.api#documentation" => "<p>A list of <code>DataSourceToIndexFieldMapping</code> objects that map attributes or\n            field names of Quip attachments to Amazon Kendra index field names. To create\n            custom fields, use the <code>UpdateIndex</code> API before you map to Quip fields. For\n            more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The\n            Quip field names must exist in your Quip custom metadata.</p>"}))
    QuipConfiguration.add_member(:inclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'InclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to include certain files in your Quip file\n            system. Files that match the patterns are included in the index. Files that don't match\n            the patterns are excluded from the index. If a file matches both an inclusion pattern\n            and an exclusion pattern, the exclusion pattern takes precedence, and the file isn't\n            included in the index.</p>"}))
    QuipConfiguration.add_member(:exclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'ExclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to exclude certain files in your Quip file\n            system. Files that match the patterns are excluded from the index. Files that don’t\n            match the patterns are included in the index. If a file matches both an inclusion\n            pattern and an exclusion pattern, the exclusion pattern takes precedence, and the file\n            isn't included in the index.</p>"}))
    QuipConfiguration.add_member(:vpc_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceVpcConfiguration, location_name: 'VpcConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information for an Amazon Virtual Private Cloud (VPC) to connect to your Quip.\n            For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/vpc-configuration.html\">Configuring a VPC</a>.</p>"}))
    QuipConfiguration.type = Types::QuipConfiguration
    ReadAccessType.add_member(:allow, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ALLOW', traits: {"smithy.api#enumValue" => "ALLOW"}))
    ReadAccessType.add_member(:deny, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DENY', traits: {"smithy.api#enumValue" => "DENY"}))
    Relevance.add_member(:freshness, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentMetadataBoolean, location_name: 'Freshness', traits: {"smithy.api#documentation" => "<p>Indicates that this field determines how \"fresh\" a document is. For example, if\n            document 1 was created on November 5, and document 2 was created on October 31, document\n            1 is \"fresher\" than document 2. Only applies to <code>DATE</code> fields.</p>"}))
    Relevance.add_member(:importance, Smithy::Schema::Shapes::ShapeRef.new(shape: Importance, location_name: 'Importance', traits: {"smithy.api#documentation" => "<p>The relative importance of the field in the search. Larger numbers provide more of a\n            boost than smaller numbers.</p>"}))
    Relevance.add_member(:duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Duration, location_name: 'Duration', traits: {"smithy.api#documentation" => "<p>Specifies the time period that the boost applies to. For example, to make the boost\n            apply to documents with the field value within the last month, you would use \"2628000s\".\n            Once the field value is beyond the specified range, the effect of the boost drops off.\n            The higher the importance, the faster the effect drops off. If you don't specify a\n            value, the default is 3 months. The value of the field is a numeric string followed by\n            the character \"s\", for example \"86400s\" for one day, or \"604800s\" for one week. </p>\n         <p>Only applies to <code>DATE</code> fields.</p>"}))
    Relevance.add_member(:rank_order, Smithy::Schema::Shapes::ShapeRef.new(shape: Order, location_name: 'RankOrder', traits: {"smithy.api#documentation" => "<p>Determines how values should be interpreted.</p>\n         <p>When the <code>RankOrder</code> field is <code>ASCENDING</code>, higher numbers are\n            better. For example, a document with a rating score of 10 is higher ranking than a\n            document with a rating score of 1.</p>\n         <p>When the <code>RankOrder</code> field is <code>DESCENDING</code>, lower numbers are\n            better. For example, in a task tracking application, a priority 1 task is more important\n            than a priority 5 task.</p>\n         <p>Only applies to <code>LONG</code> fields.</p>"}))
    Relevance.add_member(:value_importance_map, Smithy::Schema::Shapes::ShapeRef.new(shape: ValueImportanceMap, location_name: 'ValueImportanceMap', traits: {"smithy.api#documentation" => "<p>A list of values that should be given a different boost when they appear in the result\n            list. For example, if you are boosting a field called \"department\", query terms that\n            match the department field are boosted in the result. However, you can add entries from\n            the department field to boost documents with those values higher. </p>\n         <p>For example, you can add entries to the map with names of departments. If you add\n            \"HR\",5 and \"Legal\",3 those departments are given special attention when they appear in\n            the metadata of a document. When those terms appear they are given the specified\n            importance instead of the regular importance for the boost.</p>"}))
    Relevance.type = Types::Relevance
    RelevanceFeedback.add_member(:result_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ResultId, location_name: 'ResultId', traits: {"smithy.api#documentation" => "<p>The identifier of the search result that the user provided relevance feedback\n            for.</p>", "smithy.api#required" => {}}))
