    RetrieveRequest.add_member(:index_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexId, location_name: 'IndexId', traits: {"smithy.api#documentation" => "<p>The identifier of the index to retrieve relevant passages for the search.</p>", "smithy.api#required" => {}}))
    RetrieveRequest.add_member(:query_text, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryText, location_name: 'QueryText', traits: {"smithy.api#documentation" => "<p>The input query text to retrieve relevant passages for the search. Amazon Kendra\n            truncates queries at 30 token words, which excludes punctuation and stop words.\n            Truncation still applies if you use Boolean or more advanced, complex queries. For\n            example, <code>Timeoff AND October AND Category:HR</code> is counted as 3 tokens:\n                <code>timeoff</code>, <code>october</code>, <code>hr</code>. For more information,\n            see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/searching-example.html#searching-index-query-syntax\">Searching with advanced query syntax</a> in the Amazon Kendra Developer Guide. </p>", "smithy.api#required" => {}}))
    RetrieveRequest.add_member(:attribute_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeFilter, location_name: 'AttributeFilter', traits: {"smithy.api#documentation" => "<p>Filters search results by document fields/attributes. You can only provide one\n            attribute filter; however, the <code>AndAllFilters</code>, <code>NotFilter</code>, and\n                <code>OrAllFilters</code> parameters contain a list of other filters.</p>\n         <p>The <code>AttributeFilter</code> parameter means you can create a set of filtering\n            rules that a document must satisfy to be included in the query results.</p>\n         <note>\n            <p>For Amazon Kendra Gen AI Enterprise Edition indices use <code>AttributeFilter</code> to\n                enable document filtering for end users using <code>_email_id</code> or include\n                public documents (<code>_email_id=null</code>).</p>\n         </note>"}))
    RetrieveRequest.add_member(:requested_document_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentAttributeKeyList, location_name: 'RequestedDocumentAttributes', traits: {"smithy.api#documentation" => "<p>A list of document fields/attributes to include in the response. You can limit the\n            response to include certain document fields. By default, all document fields are\n            included in the response.</p>"}))
    RetrieveRequest.add_member(:document_relevance_override_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentRelevanceOverrideConfigurationList, location_name: 'DocumentRelevanceOverrideConfigurations', traits: {"smithy.api#documentation" => "<p>Overrides relevance tuning configurations of fields/attributes set at the index\n            level.</p>\n         <p>If you use this API to override the relevance tuning configured at the index level,\n            but there is no relevance tuning configured at the index level, then Amazon Kendra\n            does not apply any relevance tuning.</p>\n         <p>If there is relevance tuning configured for fields at the index level, and you use\n            this API to override only some of these fields, then for the fields you did not\n            override, the importance is set to 1.</p>"}))
    RetrieveRequest.add_member(:page_number, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PageNumber', traits: {"smithy.api#documentation" => "<p>Retrieved relevant passages are returned in pages the size of the\n                <code>PageSize</code> parameter. By default, Amazon Kendra returns the first\n            page of results. Use this parameter to get result pages after the first one.</p>"}))
    RetrieveRequest.add_member(:page_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PageSize', traits: {"smithy.api#documentation" => "<p>Sets the number of retrieved relevant passages that are returned in each page of\n            results. The default page size is 10. The maximum number of results returned is 100. If\n            you ask for more than 100 results, only 100 are returned.</p>"}))
    RetrieveRequest.add_member(:user_context, Smithy::Schema::Shapes::ShapeRef.new(shape: UserContext, location_name: 'UserContext', traits: {"smithy.api#documentation" => "<p>The user context token or user and group information.</p>"}))
    RetrieveRequest.type = Types::RetrieveRequest
    RetrieveResult.add_member(:query_id, Smithy::Schema::Shapes::ShapeRef.new(shape: QueryId, location_name: 'QueryId', traits: {"smithy.api#documentation" => "<p>The identifier of query used for the search. You also use <code>QueryId</code> to\n            identify the search when using the <a href=\"https://docs.aws.amazon.com/kendra/latest/APIReference/API_SubmitFeedback.html\">Submitfeedback</a>\n            API.</p>"}))
    RetrieveResult.add_member(:result_items, Smithy::Schema::Shapes::ShapeRef.new(shape: RetrieveResultItemList, location_name: 'ResultItems', traits: {"smithy.api#documentation" => "<p>The results of the retrieved relevant passages for the search.</p>"}))
    RetrieveResult.type = Types::RetrieveResult
    RetrieveResultItem.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: ResultId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>The identifier of the relevant passage result.</p>"}))
    RetrieveResultItem.add_member(:document_id, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentId, location_name: 'DocumentId', traits: {"smithy.api#documentation" => "<p>The identifier of the document.</p>"}))
    RetrieveResultItem.add_member(:document_title, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentTitle, location_name: 'DocumentTitle', traits: {"smithy.api#documentation" => "<p>The title of the document.</p>"}))
    RetrieveResultItem.add_member(:content, Smithy::Schema::Shapes::ShapeRef.new(shape: Content, location_name: 'Content', traits: {"smithy.api#documentation" => "<p>The contents of the relevant passage.</p>"}))
    RetrieveResultItem.add_member(:document_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'DocumentURI', traits: {"smithy.api#documentation" => "<p>The URI of the original location of the document.</p>"}))
    RetrieveResultItem.add_member(:document_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentAttributeList, location_name: 'DocumentAttributes', traits: {"smithy.api#documentation" => "<p>An array of document fields/attributes assigned to a document in the search results.\n            For example, the document author (<code>_author</code>) or the source URI\n                (<code>_source_uri</code>) of the document.</p>"}))
    RetrieveResultItem.add_member(:score_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: ScoreAttributes, location_name: 'ScoreAttributes', traits: {"smithy.api#documentation" => "<p>The confidence score bucket for a retrieved passage result. The confidence bucket\n            provides a relative ranking that indicates how confident Amazon Kendra is that the\n            response is relevant to the query.</p>"}))
    RetrieveResultItem.type = Types::RetrieveResultItem
    RetrieveResultItemList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: RetrieveResultItem)
    S3DataSourceConfiguration.add_member(:bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: S3BucketName, location_name: 'BucketName', traits: {"smithy.api#documentation" => "<p>The name of the bucket that contains the documents.</p>", "smithy.api#required" => {}}))
    S3DataSourceConfiguration.add_member(:inclusion_prefixes, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'InclusionPrefixes', traits: {"smithy.api#documentation" => "<p>A list of S3 prefixes for the documents that should be included in the index.</p>"}))
    S3DataSourceConfiguration.add_member(:inclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'InclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of glob patterns (patterns that can expand a wildcard pattern into a list of\n            path names that match the given pattern) for certain file names and file types to include \n            in your index. If a document matches both an inclusion and exclusion prefix or pattern, \n            the exclusion prefix takes precendence and the document is not indexed. Examples of glob \n            patterns include:</p>\n         <ul>\n            <li>\n               <p>\n                  <i>/myapp/config/*</i>—All files inside config directory.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*.png</i>—All .png files in all directories.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*.{png, ico, md}</i>—All .png, .ico or .md files in all\n                    directories.</p>\n            </li>\n            <li>\n               <p>\n                  <i>/myapp/src/**/*.ts</i>—All .ts files inside src directory (and all\n                    its subdirectories).</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/!(*.module).ts</i>—All .ts files but not .module.ts</p>\n            </li>\n            <li>\n               <p>\n                  <i>*.png , *.jpg</i>—All PNG and JPEG image files\n                    in a directory (files with the extensions .png and .jpg).</p>\n            </li>\n            <li>\n               <p>\n                  <i>*internal*</i>—All files in a directory that\n                    contain 'internal' in the file name, such as 'internal', 'internal_only',\n                    'company_internal'.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*internal*</i>—All internal-related files in\n                    a directory and its subdirectories.</p>\n            </li>\n         </ul>\n         <p>For more examples, see <a href=\"https://docs.aws.amazon.com/cli/latest/reference/s3/#use-of-exclude-and-include-filters\">Use of Exclude and\n            Include Filters</a> in the Amazon Web Services CLI Command Reference.</p>"}))
    S3DataSourceConfiguration.add_member(:exclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'ExclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of glob patterns (patterns that can expand a wildcard pattern into a list of\n            path names that match the given pattern) for certain file names and file types to exclude \n            from your index. If a document matches both an inclusion and exclusion prefix or pattern, \n            the exclusion prefix takes precendence and the document is not indexed. Examples of glob \n            patterns include:</p>\n         <ul>\n            <li>\n               <p>\n                  <i>/myapp/config/*</i>—All files inside config directory.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*.png</i>—All .png files in all directories.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*.{png, ico, md}</i>—All .png, .ico or .md files in all\n                    directories.</p>\n            </li>\n            <li>\n               <p>\n                  <i>/myapp/src/**/*.ts</i>—All .ts files inside src directory (and all\n                    its subdirectories).</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/!(*.module).ts</i>—All .ts files but not .module.ts</p>\n            </li>\n            <li>\n               <p>\n                  <i>*.png , *.jpg</i>—All PNG and JPEG image files\n                    in a directory (files with the extensions .png and .jpg).</p>\n            </li>\n            <li>\n               <p>\n                  <i>*internal*</i>—All files in a directory that\n                    contain 'internal' in the file name, such as 'internal', 'internal_only',\n                    'company_internal'.</p>\n            </li>\n            <li>\n               <p>\n                  <i>**/*internal*</i>—All internal-related files in\n                    a directory and its subdirectories.</p>\n            </li>\n         </ul>\n         <p>For more examples, see <a href=\"https://docs.aws.amazon.com/cli/latest/reference/s3/#use-of-exclude-and-include-filters\">Use of Exclude and\n                Include Filters</a> in the Amazon Web Services CLI Command Reference.</p>"}))
    S3DataSourceConfiguration.add_member(:documents_metadata_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DocumentsMetadataConfiguration, location_name: 'DocumentsMetadataConfiguration'))
    S3DataSourceConfiguration.add_member(:access_control_list_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: AccessControlListConfiguration, location_name: 'AccessControlListConfiguration', traits: {"smithy.api#documentation" => "<p>Provides the path to the S3 bucket that contains the user context filtering files for\n            the data source. For the format of the file, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/s3-acl.html\">Access control for S3 data\n            sources</a>.</p>"}))
