    SaaSConfiguration.add_member(:organization_name, Smithy::Schema::Shapes::ShapeRef.new(shape: OrganizationName, location_name: 'OrganizationName', traits: {"smithy.api#documentation" => "<p>The name of the organization of the GitHub Enterprise Cloud (SaaS) account you want to\n            connect to. You can find your organization name by logging into GitHub desktop and\n            selecting <b>Your organizations</b> under your profile picture\n            dropdown.</p>", "smithy.api#required" => {}}))
