    SalesforceChatterFeedConfiguration.add_member(:document_data_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentDataFieldName', traits: {"smithy.api#documentation" => "<p>The name of the column in the Salesforce FeedItem table that contains the content to\n            index. Typically this is the <code>Body</code> column.</p>", "smithy.api#required" => {}}))
    SalesforceChatterFeedConfiguration.add_member(:document_title_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentTitleFieldName', traits: {"smithy.api#documentation" => "<p>The name of the column in the Salesforce FeedItem table that contains the title of the\n            document. This is typically the <code>Title</code> column.</p>"}))
    SalesforceChatterFeedConfiguration.add_member(:field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'FieldMappings', traits: {"smithy.api#documentation" => "<p>Maps fields from a Salesforce chatter feed into Amazon Kendra index\n            fields.</p>"}))
    SalesforceChatterFeedConfiguration.add_member(:include_filter_types, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceChatterFeedIncludeFilterTypes, location_name: 'IncludeFilterTypes', traits: {"smithy.api#documentation" => "<p>Filters the documents in the feed based on status of the user. When you specify\n                <code>ACTIVE_USERS</code> only documents from users who have an active account are\n            indexed. When you specify <code>STANDARD_USER</code> only documents for Salesforce\n            standard users are documented. You can specify both.</p>"}))
    SalesforceChatterFeedConfiguration.type = Types::SalesforceChatterFeedConfiguration
    SalesforceChatterFeedIncludeFilterType.add_member(:active_user, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ACTIVE_USER', traits: {"smithy.api#enumValue" => "ACTIVE_USER"}))
    SalesforceChatterFeedIncludeFilterType.add_member(:standard_user, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STANDARD_USER', traits: {"smithy.api#enumValue" => "STANDARD_USER"}))
