    SalesforceConfiguration.add_member(:server_url, Smithy::Schema::Shapes::ShapeRef.new(shape: Url, location_name: 'ServerUrl', traits: {"smithy.api#documentation" => "<p>The instance URL for the Salesforce site that you want to index.</p>", "smithy.api#required" => {}}))
    SalesforceConfiguration.add_member(:secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SecretArn, location_name: 'SecretArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an Secrets Managersecret that contains the\n            key/value pairs required to connect to your Salesforce instance. The secret must contain\n            a JSON structure with the following keys:</p>\n         <ul>\n            <li>\n               <p>authenticationUrl - The OAUTH endpoint that Amazon Kendra connects to get\n                    an OAUTH token. </p>\n            </li>\n            <li>\n               <p>consumerKey - The application public key generated when you created your\n                    Salesforce application.</p>\n            </li>\n            <li>\n               <p>consumerSecret - The application private key generated when you created your\n                    Salesforce application.</p>\n            </li>\n            <li>\n               <p>password - The password associated with the user logging in to the Salesforce\n                    instance.</p>\n            </li>\n            <li>\n               <p>securityToken - The token associated with the user logging in to the\n                    Salesforce instance.</p>\n            </li>\n            <li>\n               <p>username - The user name of the user logging in to the Salesforce\n                    instance.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    SalesforceConfiguration.add_member(:standard_object_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceStandardObjectConfigurationList, location_name: 'StandardObjectConfigurations', traits: {"smithy.api#documentation" => "<p>Configuration of the Salesforce standard objects that Amazon Kendra\n            indexes.</p>"}))
    SalesforceConfiguration.add_member(:knowledge_article_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceKnowledgeArticleConfiguration, location_name: 'KnowledgeArticleConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information for the knowledge article types that Amazon Kendra\n            indexes. Amazon Kendra indexes standard knowledge articles and the standard fields\n            of knowledge articles, or the custom fields of custom knowledge articles, but not\n            both.</p>"}))
    SalesforceConfiguration.add_member(:chatter_feed_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceChatterFeedConfiguration, location_name: 'ChatterFeedConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information for Salesforce chatter feeds.</p>"}))
    SalesforceConfiguration.add_member(:crawl_attachments, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CrawlAttachments', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether Amazon Kendra should index attachments to Salesforce\n            objects.</p>"}))
    SalesforceConfiguration.add_member(:standard_object_attachment_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceStandardObjectAttachmentConfiguration, location_name: 'StandardObjectAttachmentConfiguration', traits: {"smithy.api#documentation" => "<p>Configuration information for processing attachments to Salesforce standard objects.\n        </p>"}))
    SalesforceConfiguration.add_member(:include_attachment_file_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'IncludeAttachmentFilePatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to include certain documents in your Salesforce.\n            Documents that match the patterns are included in the index. Documents that don't match\n            the patterns are excluded from the index. If a document matches both an inclusion and\n            exclusion pattern, the exclusion pattern takes precedence and the document isn't\n            included in the index.</p>\n         <p>The pattern is applied to the name of the attached file.</p>"}))
    SalesforceConfiguration.add_member(:exclude_attachment_file_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'ExcludeAttachmentFilePatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to exclude certain documents in your Salesforce.\n            Documents that match the patterns are excluded from the index. Documents that don't\n            match the patterns are included in the index. If a document matches both an inclusion\n            and exclusion pattern, the exclusion pattern takes precedence and the document isn't\n            included in the index.</p>\n         <p>The pattern is applied to the name of the attached file.</p>"}))
    SalesforceConfiguration.type = Types::SalesforceConfiguration
    SalesforceCustomKnowledgeArticleTypeConfiguration.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: SalesforceCustomKnowledgeArticleTypeName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the configuration.</p>", "smithy.api#required" => {}}))
    SalesforceCustomKnowledgeArticleTypeConfiguration.add_member(:document_data_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentDataFieldName', traits: {"smithy.api#documentation" => "<p>The name of the field in the custom knowledge article that contains the document data\n            to index.</p>", "smithy.api#required" => {}}))
    SalesforceCustomKnowledgeArticleTypeConfiguration.add_member(:document_title_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentTitleFieldName', traits: {"smithy.api#documentation" => "<p>The name of the field in the custom knowledge article that contains the document\n            title.</p>"}))
    SalesforceCustomKnowledgeArticleTypeConfiguration.add_member(:field_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceToIndexFieldMappingList, location_name: 'FieldMappings', traits: {"smithy.api#documentation" => "<p>Maps attributes or field names of the custom knowledge article to Amazon Kendra\n            index field names. To create custom fields, use the <code>UpdateIndex</code> API before\n            you map to Salesforce fields. For more information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/field-mapping.html\">Mapping data source fields</a>. The\n            Salesforce data source field names must exist in your Salesforce custom metadata.</p>"}))
    SalesforceCustomKnowledgeArticleTypeConfiguration.type = Types::SalesforceCustomKnowledgeArticleTypeConfiguration
