    ServiceNowKnowledgeArticleConfiguration.add_member(:document_data_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentDataFieldName', traits: {"smithy.api#documentation" => "<p>The name of the ServiceNow field that is mapped to the index document contents field\n            in the Amazon Kendra index.</p>", "smithy.api#required" => {}}))
