    ServiceNowKnowledgeArticleConfiguration.add_member(:filter_query, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceNowKnowledgeArticleFilterQuery, location_name: 'FilterQuery', traits: {"smithy.api#documentation" => "<p>A query that selects the knowledge articles to index. The query can return articles\n            from multiple knowledge bases, and the knowledge bases can be public or private.</p>\n         <p>The query string must be one generated by the ServiceNow console. For more\n            information, see <a href=\"https://docs.aws.amazon.com/kendra/latest/dg/servicenow-query.html\">Specifying documents to index with a\n                query</a>. </p>"}))
