    ServiceNowServiceCatalogConfiguration.add_member(:include_attachment_file_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'IncludeAttachmentFilePatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to include certain attachments of catalogs in\n            your ServiceNow. Item that match the patterns are included in the index. Items that\n            don't match the patterns are excluded from the index. If an item matches both an\n            inclusion and exclusion pattern, the exclusion pattern takes precedence and the item\n            isn't included in the index.</p>\n         <p>The regex is applied to the file name of the attachment.</p>"}))
    ServiceNowServiceCatalogConfiguration.add_member(:exclude_attachment_file_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'ExcludeAttachmentFilePatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to exclude certain attachments of catalogs in\n            your ServiceNow. Item that match the patterns are excluded from the index. Items that\n            don't match the patterns are included in the index. If an item matches both an inclusion\n            and exclusion pattern, the exclusion pattern takes precedence and the item isn't\n            included in the index.</p>\n         <p>The regex is applied to the file name of the attachment.</p>"}))
