    ServiceNowServiceCatalogConfiguration.add_member(:document_title_field_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceFieldName, location_name: 'DocumentTitleFieldName', traits: {"smithy.api#documentation" => "<p>The name of the ServiceNow field that is mapped to the index document title\n            field.</p>"}))
