    UpdateQuerySuggestionsConfigRequest.add_member(:index_id, Smithy::Schema::Shapes::ShapeRef.new(shape: IndexId, location_name: 'IndexId', traits: {"smithy.api#documentation" => "<p> The identifier of the index with query suggestions you want to update.</p>", "smithy.api#required" => {}}))
    UpdateQuerySuggestionsConfigRequest.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Mode, location_name: 'Mode', traits: {"smithy.api#documentation" => "<p>Set the mode to <code>ENABLED</code> or <code>LEARN_ONLY</code>.</p>\n         <p>By default, Amazon Kendra enables query suggestions. \n            <code>LEARN_ONLY</code> mode allows you to turn off query suggestions. \n            You can to update this at any time.</p>\n         <p>In <code>LEARN_ONLY</code> mode, Amazon Kendra continues to learn from new \n            queries to keep suggestions up to date for when you are ready to \n            switch to ENABLED mode again.</p>"}))
    UpdateQuerySuggestionsConfigRequest.add_member(:query_log_look_back_window_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'QueryLogLookBackWindowInDays', traits: {"smithy.api#documentation" => "<p>How recent your queries are in your query log time window.</p>\n         <p>The time window is the number of days from current day to past days.</p>\n         <p>By default, Amazon Kendra sets this to 180.</p>"}))
    UpdateQuerySuggestionsConfigRequest.add_member(:include_queries_without_user_information, Smithy::Schema::Shapes::ShapeRef.new(shape: ObjectBoolean, location_name: 'IncludeQueriesWithoutUserInformation', traits: {"smithy.api#documentation" => "<p>\n            <code>TRUE</code> to include queries without user information (i.e. all queries, \n            irrespective of the user), otherwise <code>FALSE</code> to only include queries \n            with user information.</p>\n         <p>If you pass user information to Amazon Kendra along with the queries, you can set this \n            flag to <code>FALSE</code> and instruct Amazon Kendra to only consider queries with user \n            information.</p>\n         <p>If you set to <code>FALSE</code>, Amazon Kendra only considers queries searched at least \n            <code>MinimumQueryCount</code> times across <code>MinimumNumberOfQueryingUsers</code> \n            unique users for suggestions.</p>\n         <p>If you set to <code>TRUE</code>, Amazon Kendra ignores all user information and learns \n            from all queries.</p>"}))
    UpdateQuerySuggestionsConfigRequest.add_member(:minimum_number_of_querying_users, Smithy::Schema::Shapes::ShapeRef.new(shape: MinimumNumberOfQueryingUsers, location_name: 'MinimumNumberOfQueryingUsers', traits: {"smithy.api#documentation" => "<p>The minimum number of unique users who must search a query in order for the query \n            to be eligible to suggest to your users.</p>\n         <p>Increasing this number might decrease the number of suggestions. However, this \n            ensures a query is searched by many users and is truly popular to suggest to users.</p>\n         <p>How you tune this setting depends on your specific needs.</p>"}))
    UpdateQuerySuggestionsConfigRequest.add_member(:minimum_query_count, Smithy::Schema::Shapes::ShapeRef.new(shape: MinimumQueryCount, location_name: 'MinimumQueryCount', traits: {"smithy.api#documentation" => "<p>The the minimum number of times a query must be searched in order to be \n            eligible to suggest to your users.</p>\n         <p>Decreasing this number increases the number of suggestions. However, this \n            affects the quality of suggestions as it sets a low bar for a query to be \n            considered popular to suggest to users.</p>\n         <p>How you tune this setting depends on your specific needs.</p>"}))
    UpdateQuerySuggestionsConfigRequest.add_member(:attribute_suggestions_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeSuggestionsUpdateConfig, location_name: 'AttributeSuggestionsConfig', traits: {"smithy.api#documentation" => "<p>Configuration information for the document fields/attributes that you want to base \n            query suggestions on.</p>"}))
