    WebCrawlerConfiguration.add_member(:urls, Smithy::Schema::Shapes::ShapeRef.new(shape: Urls, location_name: 'Urls', traits: {"smithy.api#documentation" => "<p>Specifies the seed or starting point URLs of the websites or the sitemap URLs of the\n            websites you want to crawl.</p>\n         <p>You can include website subdomains. You can list up to 100 seed URLs and up to three\n            sitemap URLs.</p>\n         <p>You can only crawl websites that use the secure communication protocol, Hypertext\n            Transfer Protocol Secure (HTTPS). If you receive an error when crawling a website, it\n            could be that the website is blocked from crawling.</p>\n         <p>\n            <i>When selecting websites to index, you must adhere to the <a href=\"https://aws.amazon.com/aup/\">Amazon Acceptable Use Policy</a> and all\n                other Amazon terms. Remember that you must only use Amazon Kendra Web Crawler\n                to index your own web pages, or web pages that you have authorization to\n                index.</i>\n         </p>", "smithy.api#required" => {}}))
    WebCrawlerConfiguration.add_member(:crawl_depth, Smithy::Schema::Shapes::ShapeRef.new(shape: CrawlDepth, location_name: 'CrawlDepth', traits: {"smithy.api#documentation" => "<p>The 'depth' or number of levels from the seed level to crawl. For example, the seed \n            URL page is depth 1 and any hyperlinks on this page that are also crawled are depth 2.</p>"}))
    WebCrawlerConfiguration.add_member(:max_links_per_page, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxLinksPerPage, location_name: 'MaxLinksPerPage', traits: {"smithy.api#documentation" => "<p>The maximum number of URLs on a web page to include when crawling a website. This\n            number is per web page.</p>\n         <p>As a website’s web pages are crawled, any URLs the web pages link to are also crawled.\n            URLs on a web page are crawled in order of appearance.</p>\n         <p>The default maximum links per page is 100.</p>"}))
    WebCrawlerConfiguration.add_member(:max_content_size_per_page_in_mega_bytes, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxContentSizePerPageInMegaBytes, location_name: 'MaxContentSizePerPageInMegaBytes', traits: {"smithy.api#documentation" => "<p>The maximum size (in MB) of a web page or attachment to crawl.</p>\n         <p>Files larger than this size (in MB) are skipped/not crawled.</p>\n         <p>The default maximum size of a web page or attachment is set to 50 MB.</p>"}))
    WebCrawlerConfiguration.add_member(:max_urls_per_minute_crawl_rate, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxUrlsPerMinuteCrawlRate, location_name: 'MaxUrlsPerMinuteCrawlRate', traits: {"smithy.api#documentation" => "<p>The maximum number of URLs crawled per website host per minute.</p>\n         <p>A minimum of one URL is required.</p>\n         <p>The default maximum number of URLs crawled per website host per minute is 300.</p>"}))
    WebCrawlerConfiguration.add_member(:url_inclusion_patterns, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSourceInclusionsExclusionsStrings, location_name: 'UrlInclusionPatterns', traits: {"smithy.api#documentation" => "<p>A list of regular expression patterns to include certain URLs to crawl. URLs that\n            match the patterns are included in the index. URLs that don't match the patterns are\n            excluded from the index. If a URL matches both an inclusion and exclusion pattern, the\n            exclusion pattern takes precedence and the URL file isn't included in the index.</p>"}))
